/* Protótipos locais · TCC 2027. Ilustrações SVG originais. */
(() => {
'use strict';
const P = window.PROTOTYPE_CONFIG;
const $ = s => document.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = n => new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n/100);
const paths = {arrow:'M5 12h14m-5-5 5 5-5 5',back:'M19 12H5m5-5-5 5 5 5',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',play:'m8 4 13 8-13 8Z',pause:'M8 4v16M16 4v16',check:'m5 12 4 4L19 6',plus:'M12 5v14M5 12h14',upload:'M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5',download:'M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4',folder:'M3 7h18v13H3ZM3 7V4h6l3 3',desktop:'M3 3h18v13H3ZM8 21h8m-4-5v5',phone:'M7 2h10v20H7ZM11 18h2',reset:'M3 10a9 9 0 1 1 2 9M3 4v6h6',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2Zm6-2v16m6-14v16',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Zm13 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0',cart:'M2 3h3l3 12h11l3-8H6M9 21h.01M18 21h.01',edit:'m4 16 12-12 4 4L8 20H4Zm10-10 4 4',shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6Zm-4 10 3 3 5-6',clock:'M12 7v5l4 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',close:'m6 6 12 12M6 18 18 6'};
const icon = n => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.arrow}"/></svg>`;
const btn = (label,go,primary=false,ico='arrow') => `<button type="button" class="btn ${primary?'primary':''}" data-go="${go}">${label}${ico?icon(ico):''}</button>`;
const act = (label,action,primary=false,extra='',ico='') => `<button type="button" class="btn ${primary?'primary':''}" data-action="${action}" ${extra}>${ico?icon(ico):''}${label}</button>`;
const tag = (label,cls='') => `<span class="pill ${cls}">${label}</span>`;
const head = (title,sub='',action='') => `<div class="screen-heading"><div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`;
const kv = (k,v) => `<div class="kv"><span>${k}</span><strong>${v}</strong></div>`;
const works = [
 {id:0,title:'Linha de órbita',type:'Anime',author:'Estúdio Lume',info:'1 episódio · 30 s de amostra',desc:'Uma entregadora encontra uma estação que só aparece ao entardecer.',color:'#ff873c'},
 {id:1,title:'Maré de tinta',type:'Mangá',author:'Nina Vale',info:'Capítulo 1 · 4 páginas',desc:'Cadernos esquecidos na praia começam a contar a mesma história.',color:'#5d9e9e'},
 {id:2,title:'Cidade em pausa',type:'Anime',author:'Coletivo Quadro',info:'1 episódio · 30 s de amostra',desc:'Quando o último trem para, os desenhos dos muros ganham movimento.',color:'#9a81cc'},
 {id:3,title:'Jardim de papel',type:'Mangá',author:'Lia Costa',info:'Capítulo 1 · 4 páginas',desc:'Uma biblioteca guarda sementes entre as páginas de cada livro.',color:'#c3bb73'}
];
const dishes = [
 {id:0,name:'Ravioli da casa',category:'Principais',desc:'Massa recheada de ricota, molho de tomate e manjericão.',price:4290,allergens:'Contém trigo, leite e ovos.',color:'#c45c35'},
 {id:1,name:'Salada da horta',category:'Entradas',desc:'Folhas frescas, tomate, grão-de-bico e molho de limão.',price:2890,allergens:'Molho com mostarda. Consulte a equipe sobre restrições.',color:'#638447'},
 {id:2,name:'Torta de chocolate',category:'Sobremesas',desc:'Fatia de chocolate com calda de frutas vermelhas.',price:2990,allergens:'Contém trigo, leite e ovos.',color:'#5e382a'}
];
function initial(){return {route:P.initial,role:P.roles[0].id,view:'desktop',query:'',filter:'Todos',selected:0,favorites:[],uploaded:null,approved:false,playing:false,time:0,subtitles:true,page:1,fileNames:[],records:[{id:'CAM-014',title:'Ave junto à água',habitat:'Margem de rio',notes:'Pousada em um galho baixo. Observação de exemplo.',kind:0,reviewed:false},{id:'CAM-015',title:'Folha de sub-bosque',habitat:'Floresta de terra firme',notes:'Registro ilustrativo da superfície da folha.',kind:1,reviewed:false},{id:'CAM-016',title:'Copa em regeneração',habitat:'Área em regeneração',notes:'Registro ilustrativo de cobertura vegetal.',kind:2,reviewed:false}],recordIndex:0,votes:{},dataset:false,frame:0,excluded:[],mask:true,annotations:{},baseline:false,dish:0,quantity:1,cart:{},prices:dishes.map(d=>d.price),availability:[true,true,true],placed:false,order:null,orderStatus:0};}
let S=initial(), timer=null, toastTimer=null;
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3200);}
function download(name,data){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Arquivo de demonstração exportado.');}
function go(route){if(!P.screens.some(s=>s.id===route))return;S.playing=false;clearInterval(timer);S.route=route;const screen=P.screens.find(s=>s.id===route);if(!P.roles.find(r=>r.id===S.role).screens.includes(route))S.role=P.roles.find(r=>r.screens.includes(route)).id;render();$('#app-title')?.focus({preventScroll:true});}
function cover(id=0,wide=false){const w=works[id%4],c=w.color;return `<svg viewBox="0 0 ${wide?'560 360':'300 400'}" role="img" aria-label="Ilustração original de ${esc(w.title)}" preserveAspectRatio="xMidYMid slice"><rect width="560" height="450" fill="${c}"/><circle cx="245" cy="95" r="71" fill="#fff6e8" opacity=".86"/><path d="M-20 215 75 110 165 230 265 138 410 295 580 180V450H0" fill="#302734" opacity=".35"/><path d="M0 300h45V180h35v120h20V230h45v70h15V145h35v155h33V215h44v85h39V170h52v130h65V235h45v65h90v150H0" fill="#221c29"/><path d="M0 340 560 270M0 370 560 300" stroke="#fff6e8" stroke-width="2" opacity=".4"/><path d="M${wide?'315':'170'} 320q-20-55 0-87q20-16 28 6l10 81" fill="#fff6e8"/><circle cx="${wide?'327':'183'}" cy="220" r="17" fill="#211c28"/><path d="m${wide?'310':'166'} 318-14 45m37-45 17 45" stroke="#fff6e8" stroke-width="9"/><g fill="#ffda83">${Array.from({length:9},(_,i)=>`<rect x="${12+i*38}" y="${260-i%3*20}" width="6" height="10"/>`).join('')}</g><text x="22" y="${wide?'48':'47'}" font-family="sans-serif" font-size="12" fill="#211c28" letter-spacing="5">KOMA / ORIGINAL</text><text x="22" y="${wide?'338':'375'}" font-family="sans-serif" font-weight="700" font-size="${wide?'21':'18'}" fill="#fff6e8">${esc(w.title.toUpperCase())}</text></svg>`;}
function evidence(kind=0){return `<svg viewBox="0 0 500 380" role="img" aria-label="Ilustração de registro de campo, não é uma fotografia real"><rect width="500" height="380" fill="#dbe5c9"/><circle cx="380" cy="80" r="64" fill="#f2efd2"/><path d="M0 200Q100 80 180 180T500 160V380H0" fill="#aac09b"/><path d="M0 270Q110 190 220 260T500 220V380H0" fill="#648368"/><path d="M0 350Q140 280 250 340T500 300V380H0" fill="#4b797b"/><path d="M20 350 410 175" stroke="#5c6243" stroke-width="18" stroke-linecap="round"/>${kind===0?'<ellipse cx="270" cy="195" rx="61" ry="41" fill="#315b3f" transform="rotate(-12 270 195)"/><circle cx="319" cy="164" r="30" fill="#315b3f"/><path d="m341 162 48 10-50 8" fill="#ae582f"/><path d="m223 211-60 18 47-39" fill="#244d36"/><path d="M241 184q25 8 47 36l-42-3" fill="#8ba29a"/><circle cx="326" cy="158" r="4" fill="#f5efd8"/><path d="m270 228-3 23m25-28-8 20" stroke="#ae582f" stroke-width="4"/>':'<path d="M180 275Q100 160 205 70q140 70 85 180-60 45-110 25" fill="#315b3f"/><path d="m191 280 45-176m-29 94-49-34m61-12 43-34m-64 106 64-22" fill="none" stroke="#abc58a" stroke-width="4"/>'}<text x="24" y="355" fill="#fffdf4" font-family="monospace" font-size="11">REGISTRO ILUSTRATIVO · DEMONSTRAÇÃO</text></svg>`;}
function sky(frame=0,mask=false){return `<svg viewBox="0 0 400 400" role="img" aria-label="Imagem all-sky sintética ${frame+1}${mask?', com máscara ilustrativa':''}"><defs><radialGradient id="sky${frame}${mask?'m':''}"><stop stop-color="#244873"/><stop offset=".8" stop-color="#162445"/><stop offset="1" stop-color="#090e22"/></radialGradient><clipPath id="clip${frame}${mask?'m':''}"><circle cx="200" cy="200" r="164"/></clipPath></defs><rect width="400" height="400" fill="#080f24"/><circle cx="200" cy="200" r="164" fill="url(#sky${frame}${mask?'m':''})"/><g clip-path="url(#clip${frame}${mask?'m':''})">${Array.from({length:7},(_,i)=>`<path d="M-30 ${100+i*34-frame*5}q140 ${-90+i*5} 240 ${i*10}T450 ${110+i*37}" fill="none" stroke="${i%2?'#62d6c7':'#87a6dc'}" stroke-width="${8+i%3*7}" opacity="${.12+i*.025}"/>`).join('')}${Array.from({length:40},(_,i)=>`<circle cx="${50+i*67%310}" cy="${50+i*113%300}" r="${i%4===0?1.6:.8}" fill="#d6e6ff" opacity="${.25+i%5*.1}"/>`).join('')}${frame===3?'<ellipse cx="190" cy="145" rx="130" ry="70" fill="#9dacc8" opacity=".36"/>':''}${mask?'<path d="M116 110q33-29 51 17l70 155q-13 37-43 12l-66-140Z" fill="#5ee8d5" fill-opacity=".25" stroke="#5ee8d5" stroke-width="2" stroke-dasharray="6 4"/>':''}</g><circle cx="200" cy="200" r="164" fill="none" stroke="#3c557f"/><path d="M200 31v12m0 314v12M31 200h12m314 0h12" stroke="#91a9ff"/><g fill="#a9badb" font-family="monospace" font-size="11"><text x="196" y="22">N</text><text x="194" y="388">S</text><text x="12" y="204">O</text><text x="379" y="204">L</text></g><text x="20" y="379" font-family="monospace" font-size="9" fill="#718bb8">SIMULADO / EXEMPLO-01</text></svg>`;}
function plate(id=0){return `<svg viewBox="0 0 420 330" role="img" aria-label="Ilustração de ${esc(dishes[id].name)}"><ellipse cx="214" cy="190" rx="155" ry="111" fill="#6a5132" opacity=".12"/><ellipse cx="210" cy="165" rx="155" ry="122" fill="#fffdf5"/><ellipse cx="210" cy="165" rx="123" ry="93" fill="#f3ead8"/><ellipse cx="210" cy="165" rx="114" ry="85" fill="${id===0?'#d47749':id===1?'#d0d5a6':'#ede1c6'}"/>${id===0?Array.from({length:7},(_,i)=>`<g transform="translate(${135+i%3*65} ${120+Math.floor(i/3)*44}) rotate(${i*17})"><rect x="-21" y="-17" width="45" height="34" rx="8" fill="#eec57c" stroke="#c79a55" stroke-width="2"/><path d="M-12-9h27v18h-27Z" fill="#f6d9a0"/><path d="M-20-9h-5m5 8h-5m5 8h-5m50-16h-5m5 8h-5m5 8h-5" stroke="#b78848"/></g>`).join(''):id===1?Array.from({length:15},(_,i)=>`<ellipse cx="${125+i*57%175}" cy="${105+i*41%120}" rx="${19+i%3*5}" ry="${10+i%4*2}" transform="rotate(${i*31} ${125+i*57%175} ${105+i*41%120})" fill="${['#628746','#8ba54c','#47723d','#bd5d39'][i%4]}"/>`).join(''):'<path d="m130 210 45-112 130 109Z" fill="#5b382e"/><path d="m130 188 45-112 130 109Z" fill="#402920"/><path d="m130 188 175-3v22l-175 3Z" fill="#7d5140"/><path d="m170 118 84 61" stroke="#f4dab4" stroke-width="4"/><circle cx="282" cy="134" r="13" fill="#9d363b"/><circle cx="300" cy="147" r="12" fill="#b64546"/>'}<path d="M190 157q-30-38-43-16 3 25 43 16m2 0q25-38 40-17-7 25-40 17" fill="#476e39"/><circle cx="160" cy="218" r="3" fill="#576a36"/><circle cx="278" cy="107" r="3" fill="#576a36"/></svg>`;}
function shellNav(){const nav=P.nav.map(n=>`<button type="button" data-go="${n[1]}" class="${S.route===n[1]?'active':''}">${n[0]}${n[1]==='cart'&&cartCount()?` (${cartCount()})`:''}</button>`).join('');return `<div class="app-brand"><img src="../identidade-visual/assets/${P.dark?'simbolo-negativo.svg':'simbolo.svg'}" alt="">${P.name}</div><nav class="app-nav" aria-label="Navegação do aplicativo">${nav}</nav><span class="user-avatar" title="Perfil de demonstração">${P.avatar}</span>`;}
function render(preserve=false){const active=preserve?document.activeElement:null,id=active?.id,start=active?.selectionStart;const route=P.screens.find(x=>x.id===S.route);const role=P.roles.find(r=>r.id===S.role);$('#roles').innerHTML=P.roles.map(r=>`<button type="button" data-role="${r.id}" class="${r.id===S.role?'active':''}" aria-pressed="${r.id===S.role}">${r.name}</button>`).join('');$('#screens').innerHTML=role.screens.map((id,i)=>{const r=P.screens.find(s=>s.id===id);return `<button type="button" data-go="${id}" class="${id===S.route?'active':''}" ${id===S.route?'aria-current="page"':''}><span>${String(i+1).padStart(2,'0')}</span><span>${r.title}</span></button>`;}).join('');$('#breadcrumb').innerHTML=`${P.name} / ${role.name} / <strong>${route.title}</strong>`;$('#app-bar').innerHTML=shellNav();$('#app-content').innerHTML=({koma:koma,coro:coro,iono:iono,mesa:mesa}[P.id])();const heading=$('#app-content h1');if(heading){heading.id='app-title';heading.tabIndex=-1;}$('#instruction').innerHTML=`<strong>${route.title}.</strong> ${route.note}`;const idx=role.screens.indexOf(S.route);$('#flow-prev').disabled=idx===0;$('#flow-next').disabled=idx===role.screens.length-1;$('#app-window').classList.toggle('mobile',S.view==='mobile');document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===S.view);b.setAttribute('aria-pressed',b.dataset.view===S.view);});if(preserve&&id){const el=document.getElementById(id);if(el){el.focus({preventScroll:true});if(typeof start==='number')try{el.setSelectionRange(start,start);}catch{}}}document.title=`${route.title} · Protótipo ${P.name}`;}
function workList(list){return `<div class="grid-4">${list.map(w=>`<button class="work-card" type="button" data-action="work" data-id="${w.id}"><div class="work-art">${cover(w.id)}${tag(w.type)}</div><h3>${esc(w.title)}</h3><p>${esc(w.author)} · Obra fictícia</p></button>`).join('')}</div>`;}
function koma(){const w=works[S.selected%4];switch(S.route){
case 'catalog':{const list=works.filter(w=>(S.filter==='Todos'||w.type===S.filter)&&w.title.toLocaleLowerCase().includes(S.query.toLocaleLowerCase()));return `<section class="koma-feature"><div class="koma-feature-copy"><div class="eyebrow">SELEÇÃO KOMA / 01</div><h1>Histórias em<br>cada quadro.</h1><p>Explore quatro obras fictícias e experimente o player ou o leitor.</p>${act('Abrir Linha de órbita','work',true,'data-id="0"','play')}</div><div class="koma-feature-art">${cover(0,true)}</div></section><div class="toolbar"><div class="tabs">${['Todos','Anime','Mangá'].map(t=>`<button type="button" data-action="filter" data-value="${t}" class="${S.filter===t?'active':''}">${t}</button>`).join('')}</div><label class="search">${icon('search')}<input id="catalog-search" aria-label="Buscar obra" placeholder="Buscar uma obra" value="${esc(S.query)}" data-search></label></div>${list.length?workList(list):'<div class="empty">Nenhuma obra encontrada. Tente outro título.</div>'}${S.approved?`<div class="message">${icon('check')} “${esc(S.uploaded.title)}” foi aprovada na moderação desta demonstração. A mídia não foi enviada.</div>`:''}<div class="status-line"><span>Catálogo fictício · ilustrações originais</span><span>Anime + mangá independente</span></div>`;}
case 'work':return `<div class="actions" style="margin-bottom:22px">${btn('Catálogo','catalog',false,'back')}${tag(w.type,'accent')}</div><div class="work-detail"><div class="work-art">${cover(w.id)}</div><div><div class="eyebrow">${esc(w.author)} / OBRA FICTÍCIA</div><h1>${esc(w.title)}</h1><p class="work-description">${w.desc}</p><p class="small muted">${w.info} · Livre · Português</p><div class="actions">${btn(w.type==='Anime'?'Assistir amostra':'Ler capítulo',w.type==='Anime'?'player':'reader',true,'play')}${act(S.favorites.includes(w.id)?'Salvo nos favoritos':'Salvar nos favoritos','favorite',false,'','heart')}</div><div class="divider"></div><h3>${w.type==='Anime'?'Episódios':'Capítulos'}</h3><button type="button" class="episode" data-go="${w.type==='Anime'?'player':'reader'}"><span class="mono">01</span><div><strong>${w.type==='Anime'?'O último trajeto':'O primeiro encontro'}</strong><small>${w.type==='Anime'?'Amostra visual animada · sem áudio':'Quatro páginas ilustradas'}</small></div>${icon('play')}</button><p class="tiny muted" style="margin-top:18px">Créditos, direitos e classificação seriam verificados antes da publicação.</p></div></div>`;
case 'player':return `${head(w.title,'Episódio 1 · amostra visual local de 30 segundos',btn('Voltar à obra','work',false,'back'))}<div class="player-screen">${cover(w.id,true)}<div class="player-overlay">${act(S.playing?'Pausar':'Reproduzir','play',true,'id="play-overlay"',S.playing?'pause':'play')}</div><div class="player-caption" id="caption" ${S.subtitles?'':'hidden'}>“Ainda há uma estação depois do fim da linha.”</div></div><div class="player-controls">${act(S.playing?'Pausar':'Reproduzir','play',false,'id="play-control"',S.playing?'pause':'play')}<input type="range" id="seek" aria-label="Posição da amostra em segundos" min="0" max="30" value="${S.time}" style="flex:1;accent-color:var(--accent)"><span id="play-time" class="mono small">00:${String(S.time).padStart(2,'0')} / 00:30</span>${act(S.subtitles?'Legendas: sim':'Legendas: não','subtitles',false,'id="subtitle-control"')}</div><div class="message">Amostra ilustrada sem áudio. No produto, o player receberia o vídeo processado e as legendas do autor.</div>${btn('Abrir meus favoritos','favorites',false,'heart')}`;
case 'reader':return `${head('Maré de tinta',`Capítulo 1 · página ${S.page} de 4`,btn('Voltar à obra','work',false,'back'))}<div class="reader-page"><div class="reader-panels">${['A maré trouxe um caderno.','As páginas estavam secas.','Este desenho… é da minha rua.','Quem escreveu o próximo encontro?'].map((t,i)=>`<div class="reader-panel">${cover((S.page+i)%4,true)}<span class="speech">${S.page===1?t:['O traço muda a cada maré.','O caminho segue pelo cais.','Um novo quadro aparece.','Continua no próximo capítulo.'][(i+S.page)%4]}</span></div>`).join('')}</div></div><div class="reader-pager">${act('Página anterior','page-prev',false,`${S.page===1?'disabled':''}`,'back')}<span class="mono">${S.page} / 4</span>${act(S.page===4?'Fim do capítulo':'Próxima página','page-next',true,`${S.page===4?'disabled':''}`,'arrow')}</div><p class="tiny muted">Quadros originais de demonstração. O progresso fica nesta sessão.</p>`;
case 'favorites':return `${head('Minha lista',`${S.favorites.length} ${S.favorites.length===1?'obra salva':'obras salvas'} nesta sessão`,btn('Explorar catálogo','catalog',true))}${S.favorites.length?workList(works.filter(w=>S.favorites.includes(w.id))):'<div class="empty">Sua lista está vazia. Abra uma obra e toque em “Salvar nos favoritos”.</div>'}<div class="message">Favoritos e progresso usam estado local nesta demonstração. Nenhuma conta foi criada.</div>`;
case 'upload':return `${head('Enviar uma obra','Área do criador · publicação passa por revisão')}${S.uploaded?`<div class="message">${icon('check')} “${esc(S.uploaded.title)}” ${S.approved?'foi aprovada':'aguarda moderação'} nesta sessão.</div>`:''}<div class="split"><form class="form panel" data-form="upload"><div><label for="work-title">Título da obra</label><input id="work-title" name="title" maxlength="80" required placeholder="Ex.: Uma janela para o céu" value="${esc(S.uploaded?.title||'Uma janela para o céu')}"></div><div class="form-row"><div><label for="work-type">Formato</label><select id="work-type" name="type"><option>Anime</option><option>Mangá</option></select></div><div><label for="work-author">Crédito principal</label><input id="work-author" name="author" maxlength="60" required value="Estúdio de exemplo"></div></div><div class="file-box">${icon('upload')}<p>Selecione um arquivo ou use a amostra. Só o nome é registrado.</p><input id="media-file" type="file" accept="video/*,image/*,.pdf" aria-label="Selecionar nome de arquivo" data-file><p id="file-status">${S.fileNames.length?esc(S.fileNames.join(', ')):'Amostra selecionada: janela-amostra.mp4'}</p></div><label class="check"><input type="checkbox" name="rights" required>Confirmo, para esta simulação, que tenho autorização dos autores e das pessoas creditadas.</label><button class="btn primary" type="submit">Enviar para revisão ${icon('arrow')}</button></form><aside class="panel"><div class="eyebrow">ANTES DA PUBLICAÇÃO</div><h2>Do arquivo ao catálogo</h2><div class="timeline-list"><div>1. Receber arquivo<small>Verificar formato, tamanho e metadados.</small></div><div>2. Preparar mídia<small>Gerar resoluções, capas e páginas.</small></div><div>3. Conferir direitos<small>Revisão por uma pessoa responsável.</small></div><div>4. Publicar<small>Somente após aprovação.</small></div></div><p class="tiny muted">Nesta tela não ocorre upload nem processamento.</p></aside></div>`;
case 'moderation':return `${head('Fila de moderação','Revisão de créditos, direitos e conteúdo')}${!S.uploaded?`<div class="empty"><p>Nenhuma obra foi enviada nesta sessão.</p>${btn('Simular envio de uma obra','upload',true)}</div>`:`<div class="split"><div class="panel"><div class="panel-header">${tag(S.approved?'Aprovada':'Aguardando revisão',S.approved?'good':'accent')}<span class="mono tiny">ENVIO / 001</span></div><h2>${esc(S.uploaded.title)}</h2>${kv('Formato',esc(S.uploaded.type))}${kv('Crédito',esc(S.uploaded.author))}${kv('Nome do arquivo',esc(S.uploaded.file))}<div class="message">O arquivo não foi transferido. Este registro permite testar o fluxo de revisão.</div><div class="actions">${act(S.approved?'Aprovada nesta sessão':'Aprovar demonstração','approve',true,S.approved?'disabled':'','check')}${act('Devolver ao criador','return',false)}</div></div><aside class="panel"><h3>Checklist de revisão</h3><ul class="rights-list"><li>Autoria e créditos informados.</li><li>Declaração de direitos marcada.</li><li>Classificação indicativa a conferir.</li><li>Reprodução e legendas a testar.</li></ul><p class="tiny muted">A aprovação simulada não verifica conteúdo ou direitos reais.</p>${btn('Ver catálogo','catalog',false,'arrow')}</aside></div>`}`;
default:return '';}}
function observationCard(r,i){return `<button type="button" class="observation" data-action="record" data-id="${i}"><span class="obs-thumb">${evidence(r.kind)}</span><span><strong>${esc(r.title)}</strong><small>${r.id} · ${esc(r.habitat)}</small><small>${r.reviewed?'Revisado na demonstração':'Aguardando classificação'}</small></span>${icon('arrow')}</button>`;}
function coro(){const r=S.records[S.recordIndex],vote=S.votes[r.id];switch(S.route){
case 'map':return `${head('Registros de campo','Campanha de exemplo · os pontos não representam locais reais',btn('Novo registro','field',true,'plus'))}<div class="split"><div class="map-canvas"><svg viewBox="0 0 600 470" aria-label="Mapa esquemático fictício" role="img"><rect width="600" height="470" fill="#dfe6ce"/><path d="M0 70 120 20 190 130 330 40 470 130 600 60V0H0M0 360 110 270 260 370 410 280 600 350V470H0" fill="#bacfab"/><path d="M320-40Q170 80 300 180T320 490" fill="none" stroke="#83adb0" stroke-width="60"/><path d="M320-40Q170 80 300 180T320 490" fill="none" stroke="#bad5ce" stroke-width="3"/><g stroke="#fff" opacity=".45">${Array.from({length:10},(_,i)=>`<path d="M${i*65} 0v470M0 ${i*55}h600"/>`).join('')}</g><text x="34" y="45" fill="#527057" font-size="11" font-family="monospace">ÁREA DEMO / SEM COORDENADAS REAIS</text><text x="355" y="280" fill="#4f7170" font-size="14" transform="rotate(-15 355 280)">Rio de exemplo</text></svg>${S.records.map((x,i)=>`<button type="button" class="map-marker ${i===S.recordIndex?'active':''}" style="left:${[31,61,72,42][i%4]}%;top:${[32,57,22,72][i%4]}%" data-action="record" data-id="${i}" aria-label="Abrir ${esc(x.title)}">${i+1}</button>`).join('')}<span class="map-caption">Mapa ilustrativo · localização generalizada</span></div><div class="map-list">${S.records.map(observationCard).join('')}</div></div><div class="status-line"><span>${S.records.length} registros de demonstração</span><span>${S.records.filter(r=>r.reviewed).length} revisados nesta sessão</span></div>`;
case 'record':return `${head(r.title,`${r.id} · campanha demonstrativa`,btn('Mapa','map',false,'back'))}<div class="split"><div class="evidence-photo">${evidence(r.kind)}${tag('Imagem de exemplo')}</div><div class="panel">${tag(r.reviewed?'Revisado':'Em classificação',r.reviewed?'good':'accent')}<h2 style="margin-top:17px">O que foi observado</h2>${kv('Habitat',esc(r.habitat))}${kv('Localização','Área fictícia, sem GPS')}${kv('Autor','Participante de exemplo')}<p class="small" style="margin-top:19px">${esc(r.notes)}</p>${r.reviewed?`<div class="message">Revisão demonstrativa: ${esc(r.result||'Registro validado como evidência ilustrativa')}.</div>`:''}<div class="actions">${btn('Classificar registro','classify',true)}${btn('Ver consenso','consensus')}</div></div></div>`;
case 'field':return `${head('Novo registro','Descreva uma observação e associe uma evidência de exemplo')}<div class="split"><form class="form panel" data-form="field"><div><label for="record-title">O que você observou?</label><input name="title" id="record-title" required maxlength="90" value="Ave na borda da mata"></div><div><label for="habitat">Habitat</label><select id="habitat" name="habitat"><option>Margem de rio</option><option>Floresta de terra firme</option><option>Área em regeneração</option></select></div><div><label for="record-notes">Anotações de campo</label><textarea name="notes" id="record-notes" required maxlength="500">Pousada em um galho. Registro fictício para testar o fluxo.</textarea></div><div class="file-box"><p>Ilustração de exemplo disponível. Selecionar arquivo usa apenas o nome.</p><input type="file" accept="image/*" data-file aria-label="Selecionar nome de imagem"><p id="file-status">${S.fileNames.length?esc(S.fileNames.join(', ')):'imagem-exemplo.svg'}</p></div><button type="submit" class="btn primary">Salvar registro de demonstração ${icon('arrow')}</button></form><aside><div class="evidence-photo">${evidence(0)}${tag('Ilustração · não é foto de campo')}</div><p class="small muted" style="margin-top:14px">A localização é generalizada. O protótipo não solicita geolocalização nem publica evidências.</p></aside></div>`;
case 'classify':return `${head('O que aparece neste registro?',r.id+' · a resposta de outras pessoas fica oculta durante a classificação')}<div class="split"><div class="evidence-photo">${evidence(r.kind)}${tag('Evidência ilustrativa')}</div><form class="panel form" data-form="classify"><h2>Uma hipótese por vez</h2>${['Ave de margem','Ave de copa','Não é possível identificar'].map((t,i)=>`<label class="choice"><input type="radio" name="choice" value="${i}" ${vote===i?'checked':''} required><span><strong>${t}</strong><small>${['Associada à borda do corpo d’água.','Associada ao estrato mais alto da vegetação.','A evidência não permite esta distinção.'][i]}</small></span></label>`).join('')}<div><label for="vote-note">Justificativa (opcional)</label><textarea id="vote-note" name="note" maxlength="300" placeholder="Qual detalhe sustenta sua escolha?"></textarea></div><button class="btn primary" type="submit">Registrar classificação ${icon('check')}</button><p class="hint">As opções são categorias didáticas; não constituem identificação taxonômica.</p></form></div>`;
case 'consensus':{const counts=[5,2,1];if(vote!==undefined)counts[vote]++;const total=counts.reduce((a,b)=>a+b,0);return `${head('Consenso da comunidade',r.id+' · contagens fictícias para demonstrar a agregação',btn('Voltar ao registro','record',false,'back'))}${vote===undefined?`<div class="empty"><p>Faça sua classificação antes de ver as respostas do grupo.</p>${btn('Classificar primeiro','classify',true)}</div>`:`<div class="grid-2"><div class="panel"><div class="eyebrow">${total} RESPOSTAS DE DEMONSTRAÇÃO</div><h2>Distribuição das hipóteses</h2>${['Ave de margem','Ave de copa','Não é possível identificar'].map((t,i)=>`<div class="bar-row"><div><span>${t}${vote===i?' · sua escolha':''}</span><strong>${counts[i]} / ${total}</strong></div><div class="bar-track"><span style="width:${counts[i]/total*100}%"></span></div></div>`).join('')}<div class="message">Maioria de votos indica acordo entre participantes. A confirmação depende da qualidade da evidência e da revisão especializada.</div></div><div class="panel"><h2>Próximo passo</h2><p class="small muted">A pessoa revisora compara a hipótese mais votada com a evidência original e registra a decisão.</p>${kv('Maior contagem','Ave de margem')}${kv('Situação',r.reviewed?'Revisado':'Revisão pendente')}<div class="actions" style="margin-top:22px">${btn('Abrir revisão','review',true)}${act('Exportar registro','export-coro',false,'','download')}</div><p class="tiny muted" style="margin-top:20px">Este fluxo não calcula risco de extinção nem substitui avaliações oficiais.</p></div></div>`}`;}
case 'review':return `${head('Revisão especializada',r.id+' · perfil de revisão demonstrativo')}<div class="split"><div class="evidence-photo">${evidence(r.kind)}${tag(r.reviewed?'Revisado':'Aguardando decisão',r.reviewed?'good':'')}</div><form class="panel form" data-form="review"><div><label for="review-result">Resultado da revisão</label><select id="review-result" name="result"><option>Evidência insuficiente para identificar a espécie</option><option>Categoria “ave de margem” mantida</option><option>Solicitar nova evidência ao participante</option></select></div><div><label for="review-note">Nota da revisão</label><textarea id="review-note" name="note" required maxlength="400">Exemplo de revisão: registrar uma imagem mais próxima e o contexto da observação.</textarea></div><button type="submit" class="btn primary">Salvar decisão simulada ${icon('check')}</button>${r.reviewed?'<div class="message">Decisão salva nesta sessão. O registro já aparece como revisado no mapa.</div>':''}${btn('Voltar ao mapa','map',false,'map')}</form></div>`;
default:return '';}}
function metricValues(){const truth=Array.from({length:64},(_,i)=>{const x=i%8,y=Math.floor(i/8);return (x===3||x===4)&&y>=1&&y<=6;});const pred=truth.map((_,i)=>{const x=i%8,y=Math.floor(i/8);return (x===2||x===3)&&y>=1&&y<=6;});let tp=0,fp=0,fn=0;truth.forEach((v,i)=>{if(v&&pred[i])tp++;else if(v)fn++;else if(pred[i])fp++;});return {truth,pred,tp,fp,fn,iou:tp/(tp+fp+fn),precision:tp/(tp+fp),recall:tp/(tp+fn)};}
function heat(bits,errors=false){const m=metricValues();return `<div class="heat-grid" aria-label="Máscara sintética de 8 por 8 células">${bits.map((v,i)=>`<i class="${v?'active':''} ${errors&&v!==m.truth[i]?'error':''}"></i>`).join('')}</div>`;}
function frames(){return `<div class="frame-strip">${Array.from({length:6},(_,i)=>`<button type="button" class="frame-thumb ${S.frame===i?'active':''}" data-action="frame" data-id="${i}" aria-label="Selecionar quadro ${i+1}, 20:${String(i*5).padStart(2,'0')}">${sky(i)}<span>20:${String(i*5).padStart(2,'0')}${S.excluded.includes(i)?' ×':''}</span></button>`).join('')}</div>`;}
function iono(){const loaded=S.dataset;switch(S.route){
case 'datasets':return `${head('Conjuntos de imagens','Análise all-sky · dados sintéticos nesta demonstração',btn('Importar conjunto','import',true,'upload'))}<div class="dataset-row"><div class="dataset-main"><span class="dataset-icon">${icon('folder')}</span><div><strong>EXEMPLO-01 · sequência all-sky</strong><small>6 quadros sintéticos · intervalo de 5 min · estação fictícia</small></div></div><div class="actions">${tag(loaded?'Carregado':'Amostra disponível',loaded?'good':'')}${act(loaded?'Abrir sequência':'Carregar demonstração','load-dataset',true)}</div></div><div class="grid-3" style="margin-top:25px"><div class="panel"><div class="eyebrow">01 / PREPARAR</div><h3>Conferir os quadros</h3><p class="small muted">Marque nuvens e descarte imagens inadequadas.</p></div><div class="panel"><div class="eyebrow">02 / ANOTAR</div><h3>Revisar as máscaras</h3><p class="small muted">Associe categorias às estruturas de exemplo.</p></div><div class="panel"><div class="eyebrow">03 / COMPARAR</div><h3>Medir uma referência</h3><p class="small muted">Compare a persistência com a máscara seguinte.</p></div></div><div class="message">As imagens e métricas deste protótipo são sintéticas. Nenhum modelo científico é executado.</div>`;
case 'import':return `${head('Importar uma sequência','Organize imagens, horários e estação antes da análise')}<div class="split"><form class="form panel" data-form="import"><div><label for="dataset-name">Nome do conjunto</label><input id="dataset-name" name="name" required value="EXEMPLO-01"></div><div class="form-row"><div><label for="station">Estação</label><input id="station" value="Estação de demonstração" name="station" required></div><div><label for="interval">Intervalo entre quadros</label><select id="interval" name="interval"><option>5 minutos</option><option>10 minutos</option><option>15 minutos</option></select></div></div><div class="file-box">${icon('upload')}<p>Escolha nomes de arquivos ou continue com os seis quadros sintéticos.</p><input type="file" multiple accept="image/*,.fits,.fit" data-file aria-label="Selecionar nomes de imagens"><p id="file-status">${S.fileNames.length?esc(S.fileNames.join(', ')):'6 imagens sintéticas disponíveis'}</p></div><button class="btn primary" type="submit">Abrir sequência de demonstração ${icon('arrow')}</button><p class="hint">Os arquivos não são lidos ou enviados. A sequência exibida continua sendo a amostra sintética.</p></form><aside class="panel"><h2>Metadados necessários</h2>${kv('Tempo','Data, hora e fuso de cada quadro')}${kv('Origem','Estação e instrumento')}${kv('Aquisição','Exposição, filtro e resolução')}${kv('Qualidade','Nuvens, Lua e obstruções')}<div class="message">No sistema completo, imagens sem metadados consistentes ficam separadas para revisão.</div></aside></div>`;
case 'quality':return `${head('Qualidade da sequência',`EXEMPLO-01 · quadro ${S.frame+1}/6 · 20:${String(S.frame*5).padStart(2,'0')} UTC`,btn('Anotar estruturas','annotation',true))}<div class="split"><div><div class="sky-image">${sky(S.frame,S.mask)}${tag('Imagem simulada')}</div>${frames()}</div><div class="panel"><div class="eyebrow">INSPEÇÃO DO QUADRO</div><h2>${S.frame===3?'Cobertura de nuvens':'Imagem de exemplo'}</h2>${kv('Horário',`20:${String(S.frame*5).padStart(2,'0')} UTC`)}${kv('Exposição','30 s · valor demonstrativo')}${kv('Qualidade',S.excluded.includes(S.frame)?'Excluído por revisão':S.frame===3?'Revisar nuvens':'Apto para o exemplo')}<div class="actions" style="margin-top:20px">${act(S.mask?'Ocultar máscara':'Mostrar máscara','mask',false,'','eye')}${act(S.excluded.includes(S.frame)?'Reincluir quadro':'Excluir quadro','exclude',false)}</div><div class="message">${S.excluded.length} de 6 quadros excluídos nesta sessão. O quarto quadro contém uma mancha ilustrativa de nuvem.</div><p class="tiny muted">A máscara mostra uma região didática. Não é uma detecção automática.</p></div></div>`;
case 'annotation':return `${head('Anotar uma estrutura',`Quadro ${S.frame+1} · máscara ilustrativa`,btn('Preparar comparação','baseline',true))}<div class="split"><div><div class="sky-image">${sky(S.frame,S.mask)}${tag('Região de exemplo')}</div>${frames()}</div><div class="panel"><h2>Rótulo da região</h2><p class="small muted">Selecione a categoria usada no registro de anotação.</p><div class="annotation-tools">${['Blob','Bubble','Indefinido'].map(t=>act(`${S.annotations[S.frame]===t?'✓ ':''}${t}`,'annotate',S.annotations[S.frame]===t,`data-value="${t}"`)).join('')}</div><div class="divider"></div>${kv('Quadro selecionado',String(S.frame+1))}${kv('Rótulo salvo',S.annotations[S.frame]||'Ainda não anotado')}${kv('Origem da máscara','Manual · exemplo sintético')}<div class="actions" style="margin-top:19px">${act(S.mask?'Ocultar máscara':'Mostrar máscara','mask',false,'','eye')}</div><p class="tiny muted" style="margin-top:20px">Blob e Bubble são rótulos do fluxo proposto. O desenho não é evidência observacional.</p></div></div>`;
case 'baseline':return `${head('Referência por persistência','Repita a máscara anterior e compare com a próxima')}<div class="grid-2"><div class="panel"><div class="eyebrow">ENTRADA / t</div><h2>Máscara anterior</h2>${heat(metricValues().pred)}<p class="small muted">Grade sintética de 8 × 8 células. A persistência mantém a mesma posição no instante seguinte.</p></div><div class="panel"><div class="eyebrow">ALVO / t + 5 MIN</div><h2>Máscara seguinte</h2>${heat(metricValues().truth)}<p class="small muted">Neste exemplo, a região foi deslocada uma coluna. Isso permite conferir a conta de sobreposição.</p></div></div><div class="message">Uma comparação científica exige separar treino, validação e teste em ordem temporal. Estes dois quadros sintéticos não estimam desempenho em dados reais.</div><div class="actions">${act('Calcular exemplo de persistência','run-baseline',true,'','play')}${tag(S.baseline?'Cálculo concluído':'Pronto para calcular',S.baseline?'good':'')}</div>`;
case 'evaluation':{const m=metricValues();return `${head('Avaliação da referência','Contagem calculada nas duas máscaras sintéticas',btn('Abrir relatório','report',true))}${!S.baseline?`<div class="empty"><p>Execute primeiro o exemplo de persistência.</p>${btn('Preparar cálculo','baseline',true)}</div>`:`<div class="metrics"><div class="metric"><strong>${(m.iou*100).toFixed(1).replace('.',',')}%</strong><span>Interseção / união · IoU</span><small>${m.tp} ÷ (${m.tp} + ${m.fp} + ${m.fn})</small></div><div class="metric"><strong>${m.tp}</strong><span>Células em comum</span><small>Verdadeiros positivos</small></div><div class="metric"><strong>${m.fp+m.fn}</strong><span>Células divergentes</span><small>${m.fp} extras + ${m.fn} ausentes</small></div></div><div class="grid-2"><div class="panel"><h3>Sobreposição célula a célula</h3>${heat(m.pred,true)}<div class="legend"><span><i style="background:#5ee8d5"></i>Em comum</span><span><i style="background:#f6ab78"></i>Divergência</span></div></div><div class="panel"><h3>Como ler o resultado</h3><p class="small">A máscara prevista ficou uma coluna atrás da referência. Metade das células previstas coincide com o alvo.</p>${kv('Precisão',`${(m.precision*100).toFixed(0)}%`)}${kv('Revocação',`${(m.recall*100).toFixed(0)}%`)}${kv('Natureza dos dados','Sintética')}<div class="message">Esses valores apenas explicam a métrica. Não são resultados de uma IA treinada.</div></div></div>`}`;}
case 'report':return `${head('Relatório da sessão','Configuração, anotações e cálculo de demonstração',act('Baixar JSON','export-iono',true,'','download'))}<div class="split"><article class="report-card"><div class="stamp">IONOLAB / RELATÓRIO DEMONSTRATIVO</div><h2>EXEMPLO-01</h2><p>Sequência sintética de seis imagens all-sky, usada para percorrer a interface de análise.</p><h3>Preparação</h3><p>${S.excluded.length} quadro(s) excluído(s). ${Object.keys(S.annotations).length} quadro(s) anotado(s). Os arquivos locais não foram transferidos.</p><h3>Referência</h3><p>${S.baseline?'Persistência calculada em duas máscaras de 8 × 8 células. IoU = 6 / 18 = 0,3333.':'Cálculo ainda não executado nesta sessão.'}</p><h3>Limite do exemplo</h3><p>Dados, estação e imagens são fictícios. O resultado não permite inferir desempenho em observações reais.</p></article><aside class="panel"><h2>O que vai no arquivo</h2>${kv('Identificação','EXEMPLO-01')}${kv('Dados de origem','demo: true')}${kv('Exclusões',String(S.excluded.length))}${kv('Anotações',String(Object.keys(S.annotations).length))}${kv('Baseline',S.baseline?'Persistência sintética':'Não executado')}<div class="actions" style="margin-top:20px">${btn('Revisar sequência','quality',false,'back')}</div></aside></div>`;
default:return '';}}
function cartCount(){return Object.values(S.cart).reduce((a,b)=>a+b,0);}
function total(){return Object.entries(S.cart).reduce((sum,[id,n])=>sum+S.prices[id]*n,0);}
function cartRows(){return Object.entries(S.cart).filter(([,n])=>n>0).map(([id,n])=>`<div class="cart-row"><div class="dish-art">${plate(+id)}</div><div class="cart-copy"><h3>${dishes[id].name}</h3><small>${money(S.prices[id])} por unidade</small><button type="button" class="remove" data-action="cart-remove" data-id="${id}">Remover</button></div><div class="counter"><button type="button" data-action="cart-minus" data-id="${id}" aria-label="Diminuir ${dishes[id].name}">−</button><span>${n}</span><button type="button" data-action="cart-plus" data-id="${id}" aria-label="Aumentar ${dishes[id].name}">+</button></div><strong class="cart-price">${money(S.prices[id]*n)}</strong></div>`).join('');}
function orderProgress(){return `<div class="step-status">${['Recebido','Em preparo','Pronto'].map((n,i)=>`<div class="${S.orderStatus>=i?'done':''}">${n}<small>${S.orderStatus===i?'Etapa atual':S.orderStatus>i?'Concluído':'Aguardando'}</small></div>`).join('')}</div>`;}
function mesa(){const d=dishes[S.dish];switch(S.route){
case 'menu':{const shown=dishes.filter(d=>(S.filter==='Todos'||d.category===S.filter)&&d.name.toLocaleLowerCase().includes(S.query.toLocaleLowerCase()));return `<div class="restaurant-head"><div><div class="eyebrow">CASA DA PRAÇA / RESTAURANTE FICTÍCIO</div><h1>Escolha com os olhos.</h1><p>Explore os pratos e simule um pedido na mesa.</p></div><div class="table-badge">MESA<strong>12</strong></div></div><div class="toolbar"><div class="tabs">${['Todos','Entradas','Principais','Sobremesas'].map(t=>`<button type="button" data-action="filter" data-value="${t}" class="${S.filter===t?'active':''}">${t}</button>`).join('')}</div><label class="search">${icon('search')}<input id="menu-search" placeholder="Buscar prato" aria-label="Buscar prato" data-search value="${esc(S.query)}"></label></div><div class="grid-3">${shown.map(d=>`<article class="dish-card"><div class="dish-art">${plate(d.id)}${tag(S.availability[d.id]?d.category:'Indisponível')}</div><div class="dish-card-copy"><h3>${d.name}</h3><p>${d.desc}</p><div class="price-row"><strong>${money(S.prices[d.id])}</strong>${act('Ver prato','dish',false,`data-id="${d.id}"`)}</div></div></article>`).join('')||'<div class="empty">Nenhum prato encontrado.</div>'}</div><div class="status-line"><span>Preços e restaurante fictícios</span>${cartCount()?btn(`Ver sacola · ${money(total())}`,'cart',true,'cart'):'<span>Sem taxa de serviço na simulação</span>'}</div>`;}
case 'dish':return `${head(d.name,d.category,btn('Cardápio','menu',false,'back'))}<div class="grid-2"><div class="dish-detail-art">${plate(d.id)}</div><div><div class="eyebrow">FEITO NA CASA / EXEMPLO</div><h2>${money(S.prices[d.id])}</h2><p class="small">${d.desc}</p><div class="allergens"><strong>Alergênicos:</strong> ${d.allergens}</div>${btn('Ver simulação na mesa','ar',false,'eye')}<div class="divider"></div><div class="actions"><div class="counter"><button type="button" data-action="quantity-minus" aria-label="Diminuir quantidade" ${S.quantity===1?'disabled':''}>−</button><span>${S.quantity}</span><button type="button" data-action="quantity-plus" aria-label="Aumentar quantidade">+</button></div>${act(`Adicionar · ${money(S.prices[d.id]*S.quantity)}`,'add-cart',true,S.availability[d.id]?'':'disabled','plus')}</div>${!S.availability[d.id]?'<div class="message">Prato indisponível. A administração pode alterar a disponibilidade.</div>':''}<p class="tiny muted" style="margin-top:20px">A ilustração demonstra a interface; não representa a porção real.</p></div></div>`;
case 'ar':return `${head('Como ficaria na mesa',d.name+' · simulação de enquadramento',btn('Detalhes do prato','dish',false,'back'))}<div class="split"><div class="ar-view"><div class="ar-target"></div><div class="ar-plate ${S.placed?'placed':''}">${plate(d.id)}</div><div class="ar-label">Ilustração 2D · câmera desligada · escala não calibrada</div><div class="ar-bottom"><span>${S.placed?'Posição simulada confirmada':'Toque em “Posicionar prato”'}</span><span>MESA 12</span></div></div><div class="panel"><div class="eyebrow">PRÉVIA DA EXPERIÊNCIA AR</div><h2>Enquadrar. Posicionar. Escolher.</h2><p class="small muted">No produto final, o cliente apontaria a câmera para uma superfície e posicionaria o modelo do prato.</p><div class="actions">${act(S.placed?'Reposicionar prato':'Posicionar prato','place',true)}${act('Adicionar à sacola','add-cart',false,S.availability[d.id]?'':'disabled','plus')}</div><div class="message">Este protótipo explica a interação usando uma ilustração. Não abre a câmera nem carrega um modelo 3D.</div>${kv('Prato',d.name)}${kv('Valor unitário',money(S.prices[d.id]))}</div></div>`;
case 'cart':return `${head('Sua sacola',`${cartCount()} item(ns) · mesa 12`,btn('Continuar escolhendo','menu',false,'back'))}${!cartCount()?`<div class="empty"><p>Adicione um prato para simular o pedido.</p>${btn('Ver cardápio','menu',true)}</div>`:`<div class="split"><div class="panel">${cartRows()}</div><aside class="panel"><h2>Resumo</h2>${kv('Itens',String(cartCount()))}${kv('Taxa de serviço','Não aplicada no exemplo')}<div class="summary-total"><span>Total</span><strong>${money(total())}</strong></div><div class="actions" style="margin-top:22px">${btn('Revisar pedido','checkout',true)}</div><p class="tiny muted" style="margin-top:16px">Totais calculados a partir dos preços deste cardápio fictício.</p></aside></div>`}`;
case 'checkout':return `${head('Confirmar simulação','Confira os itens antes de enviar à cozinha de demonstração')}${!cartCount()?`<div class="empty"><p>Sua sacola está vazia.</p>${btn('Abrir cardápio','menu',true)}</div>`:`<div class="grid-2"><div class="panel"><h2>Mesa 12 · ${cartCount()} item(ns)</h2>${Object.entries(S.cart).map(([id,n])=>kv(`${n} × ${dishes[id].name}`,money(S.prices[id]*n))).join('')}<div class="summary-total"><span>Total</span><strong>${money(total())}</strong></div>${btn('Editar sacola','cart',false,'edit')}</div><div class="panel"><div class="eyebrow">DEMONSTRAÇÃO</div><h2>Nenhuma cobrança será feita.</h2><p class="small muted">O botão abaixo simula a confirmação e cria um pedido local, visível na cozinha.</p>${act('Simular confirmação do pedido','confirm-order',true,'','check')}<div class="message">No produto, o servidor recalcula o total e confirma o pagamento antes de liberar o pedido.</div><p class="tiny muted">Não informe dados pessoais ou de cartão. Esta tela não solicita pagamento.</p></div></div>`}`;
case 'order':return `${head('Acompanhar pedido','Mesa 12 · estado compartilhado com a cozinha nesta sessão')}${!S.order?`<div class="empty"><p>Nenhum pedido foi confirmado.</p>${btn('Montar pedido','menu',true)}</div>`:`<div class="split"><div class="panel"><div class="success-mark">${icon('check')}</div><div class="eyebrow">PEDIDO DE DEMONSTRAÇÃO</div><h1 class="order-big">#${S.order.id}</h1><p class="small">${['O pedido entrou na fila da cozinha.','A cozinha iniciou o preparo.','O pedido está pronto para ser servido.'][S.orderStatus]}</p>${orderProgress()}${S.order.items.map(i=>kv(`${i.quantity} × ${i.name}`,money(i.price*i.quantity))).join('')}${kv('Total da simulação',money(S.order.total))}</div><aside class="panel"><h2>Veja o outro lado</h2><p class="small muted">Abra a cozinha e avance o pedido. Ao voltar, esta tela refletirá a nova etapa.</p>${btn('Abrir cozinha','kitchen',true)}<div class="message">Status e pedido existem apenas nesta sessão.</div></aside></div>`}`;
case 'kitchen':return `${head('Cozinha','Fila demonstrativa · mesa 12',btn('Ver como cliente','order',false,'eye'))}<div class="kitchen-columns">${['Recebidos','Em preparo','Prontos'].map((t,i)=>`<section class="kitchen-column"><h3>${t}<span>${S.order&&S.orderStatus===i?1:0}</span></h3>${S.order&&S.orderStatus===i?`<article class="order-card"><div class="eyebrow">MESA 12</div><h4>#${S.order.id}</h4><ul>${S.order.items.map(x=>`<li>${x.quantity} × ${x.name}</li>`).join('')}</ul>${i<2?act(i===0?'Iniciar preparo':'Marcar como pronto','advance-order',true):tag('Pronto para servir','good')}</article>`:'<p class="tiny muted">Nenhum pedido nesta etapa.</p>'}</section>`).join('')}</div>${!S.order?`<div class="message">Simule um pedido no cardápio para preencher a fila. ${btn('Abrir cardápio','menu')}</div>`:''}`;
case 'admin':return `${head('Editar cardápio','Altere a disponibilidade ou o preço e confira o resultado no cardápio',btn('Ver cardápio','menu',true))}<div class="panel form">${dishes.map(d=>`<div class="admin-item"><div class="dish-art">${plate(d.id)}</div><div class="admin-copy"><h3>${d.name}</h3><span class="tiny muted">${d.category}</span></div><div><label for="price-${d.id}" class="tiny">Preço · R$</label><input type="number" id="price-${d.id}" min="0.01" max="999.99" step="0.01" value="${(S.prices[d.id]/100).toFixed(2)}" data-price="${d.id}" aria-label="Preço de ${d.name}"></div><button type="button" class="availability ${S.availability[d.id]?'on':''}" data-action="availability" data-id="${d.id}" aria-pressed="${S.availability[d.id]}">${S.availability[d.id]?'Disponível':'Indisponível'}</button></div>`).join('')}</div><div class="message">As mudanças são locais. Um pedido já confirmado conserva os preços do momento da confirmação.</div>`;
default:return '';}}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.go){go(el.dataset.go);return;}if(el.dataset.role){S.role=el.dataset.role;go(P.roles.find(r=>r.id===S.role).screens[0]);return;}if(el.dataset.view){S.view=el.dataset.view;render();return;}const a=el.dataset.action,id=Number(el.dataset.id);switch(a){
case 'reset':clearInterval(timer);S=initial();render();toast('Demonstração reiniciada.');break;
case 'previous':case 'next':{const arr=P.roles.find(r=>r.id===S.role).screens;const i=arr.indexOf(S.route);go(arr[i+(a==='next'?1:-1)]);break;}
case 'filter':S.filter=el.dataset.value;render();break;
case 'work':S.selected=id;S.time=0;S.page=1;go('work');break;
case 'favorite':S.favorites=S.favorites.includes(S.selected)?S.favorites.filter(n=>n!==S.selected):[...S.favorites,S.selected];render();toast(S.favorites.includes(S.selected)?'Obra salva na sua lista.':'Obra removida da lista.');break;
case 'play':S.playing=!S.playing;if(S.time>=30)S.time=0;clearInterval(timer);render();if(S.playing)timer=setInterval(()=>{S.time++;if($('#seek'))$('#seek').value=S.time;if($('#play-time'))$('#play-time').textContent=`00:${String(S.time).padStart(2,'0')} / 00:30`;const art=$('.player-screen>svg');if(art)art.style.transform=`scale(${1+S.time*.0015}) translateX(${Math.sin(S.time/5)*2}px)`;if(S.time>=30){S.playing=false;clearInterval(timer);render();toast('Amostra concluída.');}},1000);break;
case 'subtitles':S.subtitles=!S.subtitles;$('#caption').hidden=!S.subtitles;el.innerHTML=S.subtitles?'Legendas: sim':'Legendas: não';break;
case 'page-prev':S.page=Math.max(1,S.page-1);render();break;
case 'page-next':S.page=Math.min(4,S.page+1);render();break;
case 'approve':S.approved=true;render();toast('Obra aprovada na demonstração.');break;
case 'return':S.approved=false;go('upload');toast('Envio devolvido ao criador para revisão.');break;
case 'record':S.recordIndex=id;go('record');break;
case 'export-coro':download('coro-registro-demo.json',{demo:true,record:S.records[S.recordIndex],classification:S.votes[S.records[S.recordIndex].id]});break;
case 'load-dataset':S.dataset=true;go('quality');break;
case 'frame':S.frame=id;render();break;
case 'mask':S.mask=!S.mask;render();break;
case 'exclude':S.excluded=S.excluded.includes(S.frame)?S.excluded.filter(n=>n!==S.frame):[...S.excluded,S.frame];render();break;
case 'annotate':S.annotations[S.frame]=el.dataset.value;render();toast(`Quadro ${S.frame+1}: rótulo ${el.dataset.value} salvo.`);break;
case 'run-baseline':S.baseline=true;go('evaluation');toast('Contagem sintética calculada.');break;
case 'export-iono':download('ionolab-relatorio-demo.json',{demo:true,dataset:'EXEMPLO-01',source:'Imagens e máscaras sintéticas',excludedFrames:S.excluded.map(n=>n+1),annotations:S.annotations,baseline:S.baseline?metricValues():null});break;
case 'dish':S.dish=id;S.quantity=1;S.placed=false;go('dish');break;
case 'quantity-minus':S.quantity=Math.max(1,S.quantity-1);render();break;
case 'quantity-plus':S.quantity=Math.min(20,S.quantity+1);render();break;
case 'add-cart':if(S.availability[S.dish]){S.cart[S.dish]=(S.cart[S.dish]||0)+S.quantity;go('cart');toast(`${dishes[S.dish].name} adicionado.`);}break;
case 'cart-minus':if(--S.cart[id]<=0)delete S.cart[id];render();break;
case 'cart-plus':S.cart[id]=Math.min(99,S.cart[id]+1);render();break;
case 'cart-remove':delete S.cart[id];render();break;
case 'place':S.placed=!S.placed;render();toast(S.placed?'Posição confirmada na ilustração.':'Escolha uma nova posição simulada.');break;
case 'confirm-order':if(cartCount()){const unavailable=Object.keys(S.cart).find(id=>!S.availability[id]);if(unavailable!==undefined){toast(`${dishes[unavailable].name} está indisponível. Remova da sacola.`);go('cart');return;}S.order={id:'0127',items:Object.entries(S.cart).map(([id,quantity])=>({name:dishes[id].name,price:S.prices[id],quantity})),total:total()};S.orderStatus=0;S.cart={};go('order');toast('Pedido de demonstração enviado à cozinha.');}break;
case 'advance-order':S.orderStatus=Math.min(2,S.orderStatus+1);render();toast(S.orderStatus===1?'Pedido em preparo.':'Pedido pronto para servir.');break;
case 'availability':S.availability[id]=!S.availability[id];render();toast(`${dishes[id].name}: ${S.availability[id]?'disponível':'indisponível'}.`);break;
}});
document.addEventListener('input',e=>{if(e.target.matches('[data-search]')){S.query=e.target.value;render(true);}if(e.target.id==='seek'){S.time=Number(e.target.value);$('#play-time').textContent=`00:${String(S.time).padStart(2,'0')} / 00:30`;}});
document.addEventListener('change',e=>{if(e.target.matches('[data-file]')){S.fileNames=Array.from(e.target.files).map(f=>f.name);const out=$('#file-status');if(out)out.textContent=S.fileNames.length?`${S.fileNames.join(', ')} · apenas nomes, sem envio`:'Amostra de demonstração selecionada';}if(e.target.matches('[data-price]')){const value=Number(e.target.value);if(Number.isFinite(value)&&value>=.01&&value<=999.99){S.prices[Number(e.target.dataset.price)]=Math.round(value*100);toast('Preço atualizado nesta sessão.');}else{e.target.value=(S.prices[Number(e.target.dataset.price)]/100).toFixed(2);toast('Informe um preço entre R$ 0,01 e R$ 999,99.');}}});
document.addEventListener('submit',e=>{const form=e.target;if(!form.dataset.form)return;e.preventDefault();const d=Object.fromEntries(new FormData(form));switch(form.dataset.form){
case 'upload':S.uploaded={title:d.title.trim(),type:d.type,author:d.author.trim(),file:S.fileNames[0]||'janela-amostra.mp4'};S.approved=false;go('moderation');toast('Envio local registrado para revisão.');break;
case 'field':S.records.push({id:`CAM-${String(14+S.records.length).padStart(3,'0')}`,title:d.title.trim(),habitat:d.habitat,notes:d.notes.trim(),kind:0,reviewed:false,file:S.fileNames[0]||'imagem-exemplo.svg'});S.recordIndex=S.records.length-1;go('record');toast('Registro de demonstração salvo.');break;
case 'classify':S.votes[S.records[S.recordIndex].id]=Number(d.choice);go('consensus');toast('Sua hipótese foi registrada.');break;
case 'review':S.records[S.recordIndex].reviewed=true;S.records[S.recordIndex].result=d.result;S.records[S.recordIndex].reviewNote=d.note;render();toast('Revisão salva no registro.');break;
case 'import':S.dataset=true;go('quality');toast('Sequência sintética carregada. Os arquivos não foram enviados.');break;
}});
render();
})();
